/**
 * Storage abstraction. The production implementation is S3StorageAdapter, which
 * talks to Amazon Lightsail Object Storage through its S3-compatible API.
 * MemoryStorageAdapter exists only for automated tests.
 *
 * Callers pass object keys generated by the backend (see objectKeyFor); no method
 * accepts a key that originated from a browser.
 */

export interface ObjectHead {
  sizeBytes: number;
  etag?: string;
  contentType?: string;
  lastModified?: Date;
}

export interface CompletedPart {
  partNumber: number;
  etag: string;
}

export interface ListedObject {
  key: string;
  sizeBytes: number;
  lastModified?: Date;
}

export interface PresignedRequest {
  url: string;
  method: "PUT" | "GET";
  /** Headers the client must send verbatim for the signature to be valid. */
  headers: Record<string, string>;
  expiresAt: Date;
}

export interface StorageAdapter {
  readonly name: string;
  /** Lightweight connectivity check (HeadBucket). */
  checkConnectivity(): Promise<void>;
  presignPut(key: string, opts: { contentType: string; contentLength: number; expiresInSeconds: number }): Promise<PresignedRequest>;
  presignGet(
    key: string,
    opts: { expiresInSeconds: number; contentDisposition: string; contentType: string },
  ): Promise<PresignedRequest>;
  createMultipartUpload(key: string, opts: { contentType: string }): Promise<string>;
  presignUploadPart(key: string, uploadId: string, partNumber: number, expiresInSeconds: number): Promise<PresignedRequest>;
  completeMultipartUpload(key: string, uploadId: string, parts: CompletedPart[]): Promise<void>;
  abortMultipartUpload(key: string, uploadId: string): Promise<void>;
  /** Returns null when the object does not exist. */
  headObject(key: string): Promise<ObjectHead | null>;
  /** Reads at most `length` bytes from the start of the object (for content sniffing). */
  readObjectPrefix(key: string, length: number): Promise<Uint8Array>;
  deleteObject(key: string): Promise<void>;
  listObjects(prefix: string, continuationToken?: string): Promise<{ objects: ListedObject[]; nextToken?: string }>;
}

export function objectKeyFor(customerId: string, documentId: string): string {
  return `customers/${customerId}/documents/${documentId}`;
}

export const CUSTOMER_OBJECT_PREFIX = "customers/";

export type StorageErrorKind =
  | "ACCESS_DENIED"
  | "NOT_FOUND"
  | "TIMEOUT"
  | "INVALID_SIGNATURE"
  | "EXPIRED"
  | "INCOMPLETE_UPLOAD"
  | "UNAVAILABLE"
  | "INVALID_REQUEST"
  | "UNKNOWN";

/**
 * Normalised storage failure. `message` is safe for logs; it never contains
 * credentials, signed URLs or raw provider responses.
 */
export class StorageError extends Error {
  constructor(
    public readonly kind: StorageErrorKind,
    message: string,
    public readonly retryable: boolean,
  ) {
    super(message);
    this.name = "StorageError";
  }
}
